script_dir=fileparts(mfilename('fullpath'));root_dir=fileparts(script_dir);w=fullfile(root_dir,'waveforms','09-hall-sequence');a=fullfile(root_dir,'assets','09-hall-sequence');if ~exist(a,'dir');mkdir(a);end
